sys_script_client.script:
function onSubmit() {

    /*
     * ============================================================
     * Department - Master Validation
     * ============================================================
     * Purpose:
     *  - Validate Department records before Insert/Update.
     *  - Invalid data must NOT be saved.
     *  - Valid data is allowed to continue.
     * ============================================================
     */

    var departmentName = (g_form.getValue('department_name') || '').trim();
    var departmentCode = (g_form.getValue('department_code') || '').trim();
    var description = (g_form.getValue('description') || '').trim();

    /*
     * ------------------------------------------------------------
     * 1. Department Name - Required
     * ------------------------------------------------------------
     */
    if (!departmentName) {

        g_form.showFieldMsg(
            'department_name',
            'Department Name is required.',
            'error'
        );

        return false;
    }

    /*
     * ------------------------------------------------------------
     * 2. Department Name - Maximum Length
     * ------------------------------------------------------------
     */
    if (departmentName.length > 100) {

        g_form.showFieldMsg(
            'department_name',
            'Department Name cannot exceed 100 characters.',
            'error'
        );

        return false;
    }

    /*
     * ------------------------------------------------------------
     * 3. Department Name - Basic Character Validation
     * ------------------------------------------------------------
     * Allows:
     *  - Letters
     *  - Numbers
     *  - Spaces
     *  - Hyphen
     *  - Apostrophe
     *  - Parentheses
     *  - Ampersand
     * ------------------------------------------------------------
     */
    var namePattern = /^[A-Za-z0-9][A-Za-z0-9 &'().-]*$/;

    if (!namePattern.test(departmentName)) {

        g_form.showFieldMsg(
            'department_name',
            'Department Name contains invalid characters.',
            'error'
        );

        return false;
    }

    /*
     * ------------------------------------------------------------
     * 4. Department Code - Required
     * ------------------------------------------------------------
     */
    if (!departmentCode) {

        g_form.showFieldMsg(
            'department_code',
            'Department Code is required.',
            'error'
        );

        return false;
    }

    /*
     * ------------------------------------------------------------
     * 5. Department Code - Maximum Length
     * ------------------------------------------------------------
     */
    if (departmentCode.length > 20) {

        g_form.showFieldMsg(
            'department_code',
            'Department Code cannot exceed 20 characters.',
            'error'
        );

        return false;
    }

    /*
     * ------------------------------------------------------------
     * 6. Department Code - Format Validation
     * ------------------------------------------------------------
     * Allowed:
     *  - Uppercase letters
     *  - Numbers
     *  - Hyphen
     *  - Underscore
     *
     * Examples:
     *  CARDIO
     *  CARDIO-001
     *  ICU_01
     * ------------------------------------------------------------
     */
    var codePattern = /^[A-Z0-9_-]+$/;

    if (!codePattern.test(departmentCode)) {

        g_form.showFieldMsg(
            'department_code',
            'Department Code must contain only uppercase letters, numbers, hyphen, or underscore.',
            'error'
        );

        return false;
    }

    /*
     * ------------------------------------------------------------
     * 7. Description - Maximum Length
     * ------------------------------------------------------------
     */
    if (description.length > 500) {

        g_form.showFieldMsg(
            'description',
            'Description cannot exceed 500 characters.',
            'error'
        );

        return false;
    }

    /*
     * ------------------------------------------------------------
     * ALL VALIDATIONS PASSED
     * ------------------------------------------------------------
     *
     * Returning true allows ServiceNow to continue with
     * Insert or Update.
     */
    return true;
}
